old_roll = "function rollCrate(i){const out=[];const names=['암호화 SSD','군용 무전기','광학 부품','공구 세트','의약품 박스','배터리 팩','제어 모듈'],cals=['9mm','5.56','7.62','12g'];out.push(valuable(names[i%names.length],260+Math.floor(Math.random()*650)));if(Math.random()<.72){const caliber=cals[i%cals.length],tier=Math.min(5,1+Math.floor(Math.pow(Math.random(),1.7)*5)),pack=AMMO_CALIBERS[caliber].pack;out.push(ammoItem(caliber,Math.max(6,Math.round(pack*(.55+Math.random()*.7))),tier))}if(Math.random()<.38)out.push(gearItem('med'));if(Math.random()<.24)out.push(gearItem('grenade'));if(Math.random()<.12)out.push(weaponItem(['smg','ar','shotgun','dmr'][i%4],1+.04*Math.random(),1+Math.floor(Math.random()*2)));return out}"
