old_collision = "function pointHitsBlocker(w,x,y){for(const o of w.obstacles)if(x>o.x&&x<o.x+o.w&&y>o.y&&y<o.y+o.h)return true;for(const d of w.doors)if(!d.open&&x>d.x&&x<d.x+d.w&&y>d.y&&y<d.y+d.h)return true;return false}\nfunction blocked(w,x,y,r){if(x-r<0||y-r<0||x+r>WORLD_W||y+r>WORLD_H)return true;for(const o of w.obstacles)if(circleRect(x,y,r,o))return true;for(const d of w.doors)if(!d.open&&circleRect(x,y,r,d))return true;return false}\nfunction doorOccupied(w,d){for(const a of w.actors){if(!a.dead&&circleRect(a.x,a.y,(a.r||13)+5,d))return true}return false}\nfunction moveEntity(w,e,dx,dy){let moved=false;const nx=e.x+dx;if(!blocked(w,nx,e.y,e.r)){e.x=nx;moved=true}const ny=e.y+dy;if(!blocked(w,e.x,ny,e.r)){e.y=ny;moved=true}if(moved&&e.kind&&e.kind!=='player'){e.stepDist=(e.stepDist||0)+Math.hypot(dx,dy);if(e.stepDist>=58){e.stepDist=0;addSound(w,e.x,e.y,e.kind==='pmc'?190:155,'footstep',e.id)}}return moved}"
new_collision = "function solidObstacle(w,o){return !(o.kind==='water'&&w?.map?.waterPassable)}\nfunction pointInWater(w,x,y){return !!w?.map?.waterPassable&&w.obstacles.some(o=>o.kind==='water'&&x>o.x&&x<o.x+o.w&&y>o.y&&y<o.y+o.h)}\nfunction pointHitsBlocker(w,x,y){for(const o of w.obstacles)if(solidObstacle(w,o)&&x>o.x&&x<o.x+o.w&&y>o.y&&y<o.y+o.h)return true;for(const d of w.doors)if(!d.open&&x>d.x&&x<d.x+d.w&&y>d.y&&y<d.y+d.h)return true;return false}\nfunction blocked(w,x,y,r){if(x-r<0||y-r<0||x+r>WORLD_W||y+r>WORLD_H)return true;for(const o of w.obstacles)if(solidObstacle(w,o)&&circleRect(x,y,r,o))return true;for(const d of w.doors)if(!d.open&&circleRect(x,y,r,d))return true;return false}\nfunction nearestFreePoint(w,x,y,r,maxRadius=220){if(!blocked(w,x,y,r))return{x,y};for(let rad=18;rad<=maxRadius;rad+=18){const steps=Math.max(12,Math.ceil(rad/8));for(let i=0;i<steps;i++){const a=i/steps*Math.PI*2,nx=clamp(x+Math.cos(a)*rad,r+2,WORLD_W-r-2),ny=clamp(y+Math.sin(a)*rad,r+2,WORLD_H-r-2);if(!blocked(w,nx,ny,r))return{x:nx,y:ny}}}return null}\nfunction ensureActorFree(w,a){if(!a||a.dead||!blocked(w,a.x,a.y,a.r))return true;const q=nearestFreePoint(w,a.x,a.y,a.r,260);if(!q)return false;a.x=q.x;a.y=q.y;a.cover=null;a.lastKnown=null;a.heard=null;return true}\nfunction doorOccupied(w,d){for(const a of w.actors){if(!a.dead&&circleRect(a.x,a.y,(a.r||13)+5,d))return true}return false}\nfunction moveEntity(w,e,dx,dy){let moved=false;const terrain=pointInWater(w,e.x,e.y)?(w.map.waterSpeed||.62):1;dx*=terrain;dy*=terrain;const nx=e.x+dx;if(!blocked(w,nx,e.y,e.r)){e.x=nx;moved=true}const ny=e.y+dy;if(!blocked(w,e.x,ny,e.r)){e.y=ny;moved=true}if(moved&&e.kind&&e.kind!=='player'){e.stepDist=(e.stepDist||0)+Math.hypot(dx,dy);if(e.stepDist>=58){e.stepDist=0;const wet=pointInWater(w,e.x,e.y),base=e.kind==='pmc'?190:155;addSound(w,e.x,e.y,base*(wet?1.45:1),'footstep',e.id)}}return moved}"
s = rep(s, old_collision, new_collision, 'water and unstick collision')

