new_spawn = "function spawnFillerAI(w,index=0){\n const patrols=w.patrols||PATROLS,pos=patrols[(index+(w.aiSpawnSeq||0))%patrols.length];w.aiSpawnSeq=(w.aiSpawnSeq||0)+1;\n const pmc=(w.aiSpawnSeq%4===0),kind=pmc?'pmc':'scav',guns=pmc?['ar','dmr','smg']:['smg','shotgun','pistol','ar'];\n const gunType=guns[w.aiSpawnSeq%guns.length],tier=pmc?2:1,primary=weaponItem(gunType,pmc?1.02:.92,tier),inventory=[ammoItem(WEAPONS[gunType].caliber,AMMO_CALIBERS[WEAPONS[gunType].caliber].pack,tier)];if(pmc&&Math.random()<.42){const candidates=Object.keys(WEAPON_PARTS).filter(k=>weaponAcceptsPart(primary,WEAPON_PARTS[k]));if(candidates.length){const pt=partItem(candidates[Math.floor(Math.random()*candidates.length)]);primary.parts[pt.slot]=pt}}if(Math.random()<.38)inventory.push(gearItem('med'));if(pmc&&Math.random()<.45)inventory.push(gearItem('grenade'));\n let q=null;for(let tries=0;tries<18&&!q;tries++){const x=pos.x+(Math.random()-.5)*110,y=pos.y+(Math.random()-.5)*110;if(!blocked(w,x,y,13))q={x,y}}q=q||nearestFreePoint(w,pos.x,pos.y,13,280)||{x:pos.x,y:pos.y};\n const a=makeActor(kind,q.x,q.y,pmc?`filler-pmc-${w.aiSpawnSeq}`:`filler-scav-${w.aiSpawnSeq}`,{name:pmc?`RAIDER-${60+w.aiSpawnSeq}`:`SCAV-${60+w.aiSpawnSeq}`,primary,inventory,patrols});a.filler=true;w.actors.push(a);ensureActorFree(w,a);return a\n}"
