new_ground = "function drawGround(cam){const p=snap.map?.palette||{},ground=p.ground||'#1b2223',a=p.gridA||'#1d2627',b=p.gridB||'#20292a';ctx.fillStyle=ground;ctx.fillRect(cam.x-10,cam.y-10,canvas.width+20,canvas.height+20);const sx=Math.floor(cam.x/80)*80,sy=Math.floor(cam.y/80)*80;for(let y=sy;y<cam.y+canvas.height+80;y+=80)for(let x=sx;x<cam.x+canvas.width+80;x+=80){ctx.fillStyle=((x/80+y/80)%2)?a:b;ctx.fillRect(x,y,78,78)}ctx.fillStyle=p.road||'#29363a';for(const r of snap.map?.roads||[])ctx.fillRect(r.x,r.y,r.w,r.h);ctx.fillStyle=p.line||'rgba(221,184,92,.16)';for(const r of snap.map?.roads||[]){if(r.w>r.h)ctx.fillRect(r.x,r.y+r.h/2-2,r.w,4);else ctx.fillRect(r.x+r.w/2-2,r.y,4,r.h)}ctx.save();if(snap.map?.id==='research'){ctx.strokeStyle='rgba(104,232,196,.08)';ctx.lineWidth=1;for(let x=Math.floor(cam.x/160)*160;x<cam.x+canvas.width+160;x+=160){ctx.beginPath();ctx.moveTo(x,cam.y);ctx.lineTo(x,cam.y+canvas.height);ctx.stroke()}for(let y=Math.floor(cam.y/160)*160;y<cam.y+canvas.height+160;y+=160){ctx.beginPath();ctx.moveTo(cam.x,y);ctx.lineTo(cam.x+canvas.width,y);ctx.stroke()}}else if(snap.map?.id==='harbor'){ctx.strokeStyle='rgba(126,215,239,.09)';for(let y=Math.floor(cam.y/110)*110;y<cam.y+canvas.height+110;y+=110){ctx.beginPath();for(let x=cam.x-30;x<cam.x+canvas.width+30;x+=28){const yy=y+Math.sin((x+y)*.018)*4;if(x===cam.x-30)ctx.moveTo(x,yy);else ctx.lineTo(x,yy)}ctx.stroke()}}else{ctx.fillStyle='rgba(221,184,92,.06)';for(let x=Math.floor(cam.x/240)*240;x<cam.x+canvas.width+240;x+=240)ctx.fillRect(x,cam.y,8,canvas.height)}ctx.restore()}"
m = rep(m, old_ground, new_ground, 'map visual flavor')

old_obs = "function drawObstacles(cam){for(const o of snap.obstacles){if(o.x+o.w<cam.x-40||o.x>cam.x+canvas.width+40||o.y+o.h<cam.y-40||o.y>cam.y+canvas.height+40||!rectInVision(o))continue;ctx.fillStyle=obstacleColor(o.kind);ctx.fillRect(o.x,o.y,o.w,o.h);ctx.fillStyle='rgba(255,255,255,.055)';ctx.fillRect(o.x,o.y,o.w,3);ctx.strokeStyle='rgba(0,0,0,.42)';ctx.strokeRect(o.x,o.y,o.w,o.h)}}"
new_obs = "function drawObstacles(cam){for(const o of snap.obstacles){if(o.x+o.w<cam.x-40||o.x>cam.x+canvas.width+40||o.y+o.h<cam.y-40||o.y>cam.y+canvas.height+40||!rectInVision(o))continue;ctx.fillStyle=obstacleColor(o.kind);ctx.fillRect(o.x,o.y,o.w,o.h);if(o.kind==='water'){ctx.save();ctx.strokeStyle='rgba(120,220,240,.24)';ctx.lineWidth=2;for(let y=o.y+12;y<o.y+o.h;y+=26){ctx.beginPath();ctx.moveTo(o.x+8,y);ctx.lineTo(o.x+o.w-8,y);ctx.stroke()}ctx.restore()}else{ctx.fillStyle='rgba(255,255,255,.055)';ctx.fillRect(o.x,o.y,o.w,3)}ctx.strokeStyle='rgba(0,0,0,.42)';ctx.strokeRect(o.x,o.y,o.w,o.h)}}"
m = rep(m, old_obs, new_obs, 'water visuals')

old_cross = "function drawCrosshair(){if(!session)return;let cx=mouse.x,cy=mouse.y;if(TOUCH_MODE&&snap?.player){const cam=camera(),p=visualPlayer()||snap.player;cx=p.x-cam.x+touchAim.x*150;cy=p.y-cam.y+touchAim.y*150}ctx.save();ctx.translate(cx,cy);ctx.strokeStyle='rgba(225,242,247,.92)';ctx.lineWidth=1.5;ctx.beginPath();ctx.arc(0,0,7,0,Math.PI*2);ctx.moveTo(-13,0);ctx.lineTo(-5,0);ctx.moveTo(13,0);ctx.lineTo(5,0);ctx.moveTo(0,-13);ctx.lineTo(0,-5);ctx.moveTo(0,13);ctx.lineTo(0,5);ctx.stroke();ctx.restore()}"
new_cross = "function drawCrosshair(){if(!session)return;let cx=mouse.x,cy=mouse.y;if(TOUCH_MODE&&snap?.player){const cam=camera(),p=visualPlayer()||snap.player;cx=p.x-cam.x+touchAim.x*150;cy=p.y-cam.y+touchAim.y*150}const bloom=Math.min(17,(snap?.player?.recoil||0)*150),inner=5+bloom,outer=13+bloom;ctx.save();ctx.translate(cx,cy);ctx.strokeStyle='rgba(225,242,247,.92)';ctx.lineWidth=1.5;ctx.beginPath();ctx.arc(0,0,7+bloom*.25,0,Math.PI*2);ctx.moveTo(-outer,0);ctx.lineTo(-inner,0);ctx.moveTo(outer,0);ctx.lineTo(inner,0);ctx.moveTo(0,-outer);ctx.lineTo(0,-inner);ctx.moveTo(0,outer);ctx.lineTo(0,inner);ctx.stroke();ctx.restore()}"
m = rep(m, old_cross, new_cross, 'recoil crosshair')

m = rep(m, "$('#weaponName').textContent=p.weapon?.name||'무기 없음';$('#ammoText').textContent=p.weapon?`${p.weapon.ammo} / ${p.ammoReserve||0}`:'0 / 0';",
"$('#weaponName').textContent=p.weapon?.name||'무기 없음';$('#ammoText').textContent=p.weapon?`${p.weapon.ammo} / ${p.magCapacity||WEAPONS[p.weapon.type]?.mag||0} · 예비 ${p.ammoReserve||0}`:'0 / 0';", 'hud mag cap')
m = rep(m, "if(mapHud)mapHud.textContent=snap.map?.name||roomState?.mapName||'-';",
"if(mapHud)mapHud.textContent=`${snap.map?.name||roomState?.mapName||'-'}${snap.map?.trait?` · ${snap.map.trait}`:''}`;", 'hud map trait')
m = rep(m, "realtime.on('disconnect',()=>{if(session===realtime&&!lastResultHandled){lastResultHandled=true;session=null;if(document.pointerLockElement)document.exitPointerLock?.();showResult(false,{reason:'멀티 서버 연결 끊김',kills:snap?.player?.kills||0,lootValue:0})}})",
"realtime.on('disconnect',x=>{if(session===realtime&&!lastResultHandled){lastResultHandled=true;session=null;if(document.pointerLockElement)document.exitPointerLock?.();showResult(false,{reason:x?.reason||'멀티 서버 연결 끊김',kills:snap?.player?.kills||0,lootValue:0})}})", 'disconnect reason')
mp.write_text(m, encoding='utf-8')

